content:
[
  {
    "tag": "自我盘点",
    "prompt": "我是一名{职业身份}，每周可投入{可支配小时数}小时副业。请结合我的{核心技能}和{兴趣领域}，列出5个匹配的副业方向，每个方向说明启动成本、首月预期收入和最大风险，并用表格输出。",
    "usage": "在完全没方向时，先做技能与时间的自我盘点。",
    "example": "表格列出：短视频剪辑代做/启动成本0元/首月约800元/风险是接单不稳定。"
  },
  {
    "tag": "趋势筛选",
    "prompt": "请分析{目标平台}上近半年增长最快的{行业或品类}副业赛道，选出3个适合{个人背景}新手切入的方向，分别给出需求证据、竞争程度和6个月内的变现路径，按可行性排序。",
    "usage": "想踩趋势红利、又怕选错赛道时使用。",
    "example": "推荐AI头像定制：需求增长明显、竞争中等、可通过小红书接单变现。"
  },
  {
    "tag": "成本测算",
    "prompt": "我想做{副业设想}，启动预算不超过{预算金额}元。请拆解设备、学习、获客、时间四类成本，给出低成本启动方案和回本周期估算，并指出哪些支出可以延后。",
    "usage": "验证一个副业想法是否在预算内跑得起来。",
    "example": "建议先用手机构图接单，设备支出延后，预计2个月回本。"
  },
  {
    "tag": "风险排查",
    "prompt": "我计划从事{副业方向}，请从时间冲突、资金投入、法律合规、平台规则、收入波动五个维度做风险评估，每个维度给出风险等级和一条规避建议，最后给出是否值得启动的结论。",
    "usage": "决定投入前做一次冷静的风险体检。",
    "example": "平台规则风险中等，建议先读平台带货资质要求再开号。"
  },
  {
    "tag": "资源盘点",
    "prompt": "请帮我盘点做{副业方向}所需的资源清单，分为人脉、技能、工具、渠道四类，并对照我目前拥有的{现有资源描述}，标出缺口资源和补齐方式，用清单形式输出。",
    "usage": "已有初步方向，想弄清还差哪些资源。",
    "example": "缺口：剪辑工具熟练度，补齐方式为两周内完成基础课程练习。"
  },
  {
    "tag": "模式对比",
    "prompt": "请对比{副业方向A}和{副业方向B}两种模式，从启动难度、单位时间收益、可扩展性、退出成本四个维度打分（1-5分），并针对{个人情况}给出推荐选择及理由。",
    "usage": "在两个候选方向之间犹豫不决时使用。",
    "example": "方向A总分14分更适合兼职起步，方向B更适合全职后转型。"
  },
  {
    "tag": "人群匹配",
    "prompt": "我是{年龄}岁、{职业状态}、每天可支配{时间段}的{性格特点}型人。请推荐3个匹配我作息和性格的副业方向，说明为什么适合我，并各给一个本周就能执行的第一步动作。",
    "usage": "带娃、上班族等时间碎片化人群找方向。",
    "example": "推荐音频配音：夜间可录、独处友好，第一步为录制3条样音上传平台。"
  },
  {
    "tag": "变现路径",
    "prompt": "请为{副业方向}设计从0到1的变现路径，按第1周、第1个月、第3个月三个阶段拆解动作，每个阶段写明目标、关键动作和收入预期，并指出最容易卡住的环节。",
    "usage": "选定方向后规划落地节奏，避免盲目开干。",
    "example": "第1周完成作品集3件，第1个月接首单，第3个月月收入约2000元。"
  },
  {
    "tag": "试错方案",
    "prompt": "请为{副业方向}设计一个为期{试错周期}的最小成本试错方案，包含验证假设、测试动作、成功标准和止损条件，控制在{预算}元内完成，用步骤列表输出。",
    "usage": "想先小步验证再决定是否长期投入。",
    "example": "两周内发10条内容测流量，若平均播放低于500则换选题方向。"
  },
  {
    "tag": "决策复盘",
    "prompt": "请设计一份副业方向选择评分表，包含{评估维度列表}等维度，每个维度给出权重建议和打分标准，并用我的情况{个人情况描述}代入演示一遍打分过程，输出最终推荐方向。",
    "usage": "多个方向难取舍时，用结构化打分做决策。",
    "example": "权重：兴趣30%、收益25%、时间匹配25%、风险20%，最终推荐方向为线上课程助教。"
  }
]
